// Deduplicate by symbol (in case of any duplicates)
const seen = new Set<string>();
export const NIFTY500_STOCKS: StockMeta[] = INDIAN_STOCKS.filter(s => {
  if (seen.has(s.symbol)) return false;
  seen.add(s.symbol);
  return true;
});

// Generate Yahoo Finance symbol
export function getYahooSymbol(symbol: string): string {
  return `${symbol}.NS`;
}

// Yahoo symbols for indices
export const NIFTY50_YAHOO = '^NSEI';
export const SENSEX_YAHOO  = '^BSESN';

// All unique sectors
export const SECTORS = [
  'All',
  ...Array.from(new Set(NIFTY500_STOCKS.map(s => s.sector))).sort(),
];
